import{_ as t,o as e,c as n,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Improving Business Continuity for an Existing Large Scale Ceph Infrastructure","description":"","frontmatter":{"title":"Improving Business Continuity for an Existing Large Scale Ceph Infrastructure","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Business Continuity","Disaster Recovery","CERN","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Improving_Business_Continuity_for_an_Existing_Large_Scale_Ceph_Infrastructure.md","filePath":"posts/2023/Improving_Business_Continuity_for_an_Existing_Large_Scale_Ceph_Infrastructure.md","lastUpdated":1780459816000}'),s={name:"posts/2023/Improving_Business_Continuity_for_an_Existing_Large_Scale_Ceph_Infrastructure.md"};function r(o,i,p,a,u,_){return e(),n("div",null,[...i[0]||(i[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> CERN的Ceph存储系统业务连续性与灾难恢复改进</p><p><strong>会议时间：</strong> 日期未提供</p><p><strong>会议地点：</strong> 未提供</p><p><strong>参会人员：</strong> Enrico, Abi (CERN IT部门存储组)</p><p><strong>会议内容：</strong></p><ol><li><p><strong>CERN介绍：</strong></p><ul><li>CERN位于日内瓦，运营着一个直径27公里的粒子对撞机，该对撞机建于地下100米。</li><li>CERN拥有两个计算中心，其中一个历史悠久，建于60年代末或70年代初，另一个新中心预计今年年底投入使用。</li></ul></li><li><p><strong>Ceph在CERN的应用：</strong></p><ul><li>CERN运行16个生产集群，使用Ceph的各种形式（块存储、文件存储和对象存储）。</li><li>总存储容量约为65PB，主要使用旋转硬盘，少量全闪存存储用于RocksDB和元数据池。</li><li>Ceph与OpenStack集成，为45万个CPU核心提供存储支持。</li><li>近年来，Ceph也越来越多地被用于Kubernetes和OpenShift集群。</li></ul></li><li><p><strong>业务连续性与灾难恢复：</strong></p><ul><li><strong>块存储（RBD）：</strong><ul><li>从单一RBD集群扩展到五个RBD集群，通过OpenStack提供不同性能和可用性的存储选项。</li><li>引入了存储可用性区域（Availability Zones），以提高业务的连续性。</li><li>使用RBD镜像进行灾难恢复，测试了基于日志和基于快照的镜像方法。</li><li>OpenStack Cinder备份驱动支持S3和RBD备份，RBD备份性能更优。</li></ul></li><li><strong>对象存储：</strong><ul><li>主要使用两个独立的Ceph集群，一个用于主存储，另一个用于备份。</li><li>测试了S3多站点配置，发现同步延迟和Bucket索引重分片的问题。</li><li>探索了Cloud Sync功能，用于与外部云服务同步特定Bucket。</li></ul></li><li><strong>文件系统（CephFS）：</strong><ul><li>从单一CephFS集群扩展到多个集群，根据使用场景进行划分。</li><li>测试了CephFS快照功能，发现性能影响主要集中在MDS的Finisher线程。</li></ul></li></ul></li><li><p><strong>总结与展望：</strong></p><ul><li>业务连续性通过分散存储到不同集群实现，需要与用户和上层服务协调。</li><li>灾难恢复主要通过备份和恢复实现，Ceph提供了多种备份工具和方法。</li><li>未来可能考虑使用磁带备份，并继续优化备份流程。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续测试和优化RBD、S3和CephFS的灾难恢复功能。</li><li>探索和实施更高效的备份和恢复策略，包括磁带备份。</li><li>与用户和其他IT部门协调，制定清晰的灾难恢复流程。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议在提问环节后结束，参会者对Ceph在CERN的应用和未来发展表示了兴趣和赞赏。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的Ceph相关技术和工具包括RBD、CephFS、Rados Gateway、OpenStack、Kubernetes、OpenShift等。</li></ul>',13)])])}const c=t(s,[["render",r]]);export{C as __pageData,c as default};
